// Component shared functionality
void RelativeCircleComponent::Reset()
{
	m_relativeCenter = FVector2D::ZeroVector;
	m_radius = 100.0f;
}

void RelativeCircleComponent::Serialize(FArchive& archive)
{
	archive << m_relativeCenter;
	archive << m_radius;
}

void RelativeCircleComponent::DrawComponentDebug() const
{
#if !UE_BUILD_SHIPPING
	if (!ImGui::CollapsingHeader("RelativeCircleComponent"))
	{
		return;
	}

	if (ImGui::BeginTable("ComponentValues", 2, ImGuiTableFlags_NoSavedSettings | ImGuiTableFlags_BordersInner))
	{
		ImGui::TableNextColumn();
		ImGui::Text("m_relativeCenter");
		ImGui::TableNextColumn();
		ImGui::Text("(%.2f, %.2f)", m_relativeCenter.X, m_relativeCenter.Y);
		ImGui::TableNextColumn();
		ImGui::Text("m_radius");
		ImGui::TableNextColumn();
		ImGui::Text("%.2f", m_radius);
		ImGui::EndTable();
	}
#endif //!UE_BUILD_SHIPPING
}
